import classNames from 'classnames'

import TransformText from '../../../containers/TransformText'

import {DescriptionType} from './Description.types'
import type {Props} from './Description.types'

import styles from './Description.module.css'

function Description({
  className,
  buildTypeId,
  type = DescriptionType.MAJOR_INFO,
  text,
  lineHeight,
  lines,
  textClassName,
  animated,
}: Props) {
  const classes = classNames(styles.text, className, styles[type])

  return (
    text != null && (
      <div className={classes}>
        <TransformText
          className={classNames(styles.text, textClassName, {
            [styles.animated]: animated === true,
          })}
          buildTypeId={buildTypeId}
          text={text}
          lines={lines}
          lineHeight={lineHeight}
          showLoader={false}
          trimContent
        />
      </div>
    )
  )
}

export default Description
