import type {ActiveEntityProps, BuildTypeId} from '../../../types'

export enum DescriptionType {
  MAJOR_INFO = 'majorInfo',
  MINOR_INFO = 'minorInfo',
  SUCCESS = 'success',
  ERROR = 'error',
  WARNING = 'warning',
}
export type OwnProps = ActiveEntityProps & {
  className?: string
  lineHeight?: number
  lines?: number
  textClassName?: string
}
export type StateProps = {
  text: string | null | undefined
  buildTypeId: BuildTypeId | null | undefined
  type: DescriptionType
  animated?: boolean
}

export type Props = OwnProps & StateProps
