import classNames from 'classnames'
import {
  Children,
  memo,
  type ReactNode,
  useCallback,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react'

import SequenceLoader from '../../SequenceLoader/SequenceLoader'
import type {Child} from '../../SequenceLoader/SequenceLoader.types'
import SkeletonBadge from '../SkeletonBadge/SkeletonBadge'

import MoreBadge from './MoreBadge/MoreBadge'

import styles from './ResponsiveBadgeContainer.module.css'

const MORE_BADGE_WIDTH = 48
const GAP = 4

type Props = {
  children?: ReactNode
  className?: string
}

function ResponsiveBadgeContainer({children, className}: Props) {
  const containerRef = useRef<HTMLDivElement>(null)
  const flatChildren = useMemo(() => Children.toArray(children) as Child[], [children])
  const [hiddenChildrenWidth, setHiddenChildrenWidth] = useState<number[]>(
    new Array(flatChildren.length).fill(0),
  )
  const validElements = useMemo(
    () => flatChildren.filter((_, index) => hiddenChildrenWidth[index] === 0),
    [flatChildren, hiddenChildrenWidth],
  )
  const hiddenElements = useMemo(
    () => flatChildren.filter((_, index) => hiddenChildrenWidth[index] > 0),
    [flatChildren, hiddenChildrenWidth],
  )
  const handleResize = useCallback(
    () => () => {
      const element = containerRef.current?.children[0] as HTMLElement
      if (element) {
        const containerWidth = element.offsetWidth
        const hiddenWidths: number[] = new Array(flatChildren.length).fill(0)
        let currentWidth = MORE_BADGE_WIDTH

        flatChildren.forEach((_, index) => {
          const childElement = element?.children[index]?.children[0] as HTMLElement
          const childWidth = hiddenChildrenWidth[index] || childElement?.offsetWidth || 0
          if (childWidth !== 0) {
            if (currentWidth + childWidth + GAP <= containerWidth) {
              hiddenWidths[index] = 0
              currentWidth += childWidth + GAP
            } else {
              hiddenWidths[index] = childWidth
            }
          }
        })
        setHiddenChildrenWidth(prevState => {
          const hasChanged = hiddenWidths.some((value, idx) => value !== prevState[idx])
          return hasChanged ? hiddenWidths : prevState
        })
      }
    },
    [flatChildren, hiddenChildrenWidth],
  )

  useLayoutEffect(() => {
    const element = containerRef.current
    if (element == null) {
      return undefined
    }
    const observer = new ResizeObserver(handleResize())
    observer.observe(element)
    return () => {
      observer.unobserve(element)
      observer.disconnect()
    }
  }, [children, handleResize])

  return (
    <div ref={containerRef} className={classNames(styles.container, className)}>
      <SequenceLoader
        className={styles.badges}
        loader={
          <div>
            <SkeletonBadge />
          </div>
        }
      >
        {validElements}
        <MoreBadge seqKey={'moreBadge'} hiddenChildren={hiddenElements} />
      </SequenceLoader>
    </div>
  )
}
export default memo(ResponsiveBadgeContainer)
