import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import classNames from 'classnames'
import type {ReactNode} from 'react'
import {useState} from 'react'

import Badge from '../../../Badge/Badge'
import Icon from '../../../Icon/Icon'
import Popup from '../../../Popup/Popup'
import {useSequenceLoaderReadyHandler} from '../../../SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../../SequenceLoader/SequenceLoader.types'

import styles from './MoreBadge.module.css'

type Props = {
  hiddenChildren: ReactNode[]
} & SeqProps
function MoreBadge({hiddenChildren}: Props) {
  const [open, setOpen] = useState(false)
  const togglePopup = () => {
    setOpen(prevState => !prevState)
  }
  useSequenceLoaderReadyHandler(true)

  return (
    <Dropdown
      className={classNames({[styles.hidden]: !hiddenChildren.length})}
      onShow={togglePopup}
      onHide={togglePopup}
      anchor={
        <Badge className={classNames(styles.badgeContainer, {[styles.open]: open})}>
          <Icon name={'more-options'} />
        </Badge>
      }
    >
      {hiddenChildren.length ? (
        <Popup>
          <div className={styles.wrappedContent}>{hiddenChildren}</div>
        </Popup>
      ) : (
        <></>
      )}
    </Dropdown>
  )
}
export default MoreBadge
