import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import type {QueryParams} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import type {ReactElement, ReactNode} from 'react'
import {Children, useMemo} from 'react'

import {useQueryParam, useSyncedQueryParam} from '../../../hooks/routes'
import {noop} from '../../../utils/empty'
import type {UserProperty} from '../../../utils/userProperties'
import type {HintId} from '../../packages/Hints/Hints.types'
import {RouterButton} from '../RouterLink/RouterLink'

import styles from './ModeSwitch.module.css'

export const useMode = (defaultValue?: string): string | null | undefined =>
  useQueryParam('mode', defaultValue)
type ModeProps = {
  mode: string
  label: string
  isDefault?: boolean
  isForbidden?: boolean
  isDisabled?: boolean
  children?: ReactNode
}
export function Mode({children}: ModeProps) {
  return <>{children ?? null}</>
}
type Child = ReactElement<ModeProps>
type ChildrenType = ChildrenType[] | Child | null | boolean
type Props = {
  userProperty: UserProperty
  preserveParams?: (params: QueryParams, mode: string) => QueryParams | null | undefined
  onSwitch?: (mode: string) => unknown
  children: ChildrenType
  className?: string
  headerClassName?: string
  customItems?: ReactNode
  hintId?: HintId
  param?: string
}

const ModeSwitch = ({
  userProperty,
  children,
  preserveParams = () => null,
  customItems,
  className,
  headerClassName,
  hintId,
  onSwitch = noop,
  param = 'mode',
}: Props) => {
  const childrenArray = useMemo(() => Children.toArray(children), [children]) as Child[]
  const [activeMode, setMode] = useSyncedQueryParam({
    param,
    userProperty,
    values: childrenArray
      .filter(child => child.props.isForbidden !== true)
      .map(child => child.props.mode),
    defaultValue: childrenArray.find(child => child.props.isDefault)?.props.mode,
  })
  const activeChild = childrenArray.find(child => child.props.mode === activeMode)
  return useMemo(
    () => (
      <>
        <div className={classNames(styles.header, headerClassName)} data-hint-container-id={hintId}>
          <ButtonGroup className={className}>
            {childrenArray.map(child => {
              const {mode, label, isDisabled} = child.props
              return (
                <RouterButton
                  preventScrollReset
                  key={mode}
                  active={child === activeChild}
                  params={params => ({...preserveParams(params, mode), [param]: mode})}
                  onClick={() => {
                    onSwitch(mode)
                    setMode(mode, true)
                  }}
                  disabled={isDisabled}
                >
                  {label}
                </RouterButton>
              )
            })}
          </ButtonGroup>
          {customItems}
        </div>
        {activeChild}
      </>
    ),
    [
      activeChild,
      childrenArray,
      className,
      customItems,
      headerClassName,
      hintId,
      onSwitch,
      param,
      preserveParams,
      setMode,
    ],
  )
}

export default ModeSwitch
