import {connect} from 'react-redux'

import type {State} from '../../../reducers/types'
import {getBuild, getBuildTypeDescription, getProjectDescription} from '../../../selectors'
import {isWaitReasonWithAnimation, isWaitReasonWithWarning} from '../../../utils/waitReason'

import Description from './Description'
import {DescriptionType} from './Description.types'
import type {OwnProps, StateProps} from './Description.types'

const mapStateToProps = (state: State, props: OwnProps): StateProps => {
  const {buildTypeId, projectId, buildId}: OwnProps = props
  let type = DescriptionType.MINOR_INFO
  let text: string | null | undefined
  let animated = false

  if (buildId != null) {
    const {state: buildState, status, statusText, waitReason} = getBuild(state, buildId) ?? {}

    if (buildState === 'queued') {
      text = waitReason
      type = isWaitReasonWithWarning(waitReason)
        ? DescriptionType.WARNING
        : DescriptionType.MAJOR_INFO
      animated = isWaitReasonWithAnimation(waitReason)
    } else {
      text = statusText

      if (status === 'FAILURE') {
        type = DescriptionType.ERROR
      }

      if (status === 'SUCCESS') {
        type = DescriptionType.SUCCESS
      }
    }
  } else if (buildTypeId != null) {
    text = getBuildTypeDescription(state, buildTypeId)
    type = DescriptionType.MINOR_INFO
  } else if (projectId != null) {
    text = getProjectDescription(state, projectId)
    type = DescriptionType.MINOR_INFO
  }

  return {
    text,
    type,
    buildTypeId,
    animated,
  }
}

export default connect(mapStateToProps)(Description)
